const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometry and time
  const center = ee.Geometry.Point([-1.593993, -49.053062]);
  const radius = 100 * 1000; // 100 km in meters
  const aoi = center.buffer(radius);

  const startDate = '2009-08-19';
  const endDate = '2009-08-20';

  // 2. Load Landsat 5 TM data
  const l5 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(aoi)
    .filterDate(startDate, endDate)
    .select(['SR_B1', 'SR_B2', 'SR_B3', 'SR_B4', 'SR_B5', 'SR_B7', 'QA_PIXEL']);

  const imgCount = l5.size().getInfo();
  console.log(`Landsat 5 Images Found: ${imgCount}`);

  if (imgCount === 0) {
    console.log('No images found for August 19, 2009 at this location.');
    console.log('C1');
    return;
  }

  // 3. Use first available image
  const img = ee.Image(l5.first());

  // 4. Cloud detection from QA_PIXEL band
  // Bit 3 = Cloud, Bit 4 = Cloud Shadow
  const qa = img.select('QA_PIXEL');
  const cloudMask = qa.bitwiseAnd(8).eq(0).and(qa.bitwiseAnd(16).eq(0)); // 0 = no cloud/shadow

  // 5. Calculate NDWI to separate water (rivers) from land
  const blue = img.select('SR_B1').multiply(0.0000275).add(-0.2);
  const nir = img.select('SR_B4').multiply(0.0000275).add(-0.2);
  const swir = img.select('SR_B5').multiply(0.0000275).add(-0.2);

  const ndwi = nir.subtract(swir).divide(nir.add(swir)); // Modified NDWI
  const water = ndwi.gt(0.3); // Water pixels
  const land = ndwi.lte(0.3); // Land pixels

  // 6. Cloud presence (invert cloudMask: 1 = cloud, 0 = clear)
  const cloud = cloudMask.not();

  // 7. Calculate cloud cover over land areas
  const landCloud = cloud.updateMask(land);
  const landStats = landCloud.reduceRegion({
    reducer: ee.Reducer.sum().combine(ee.Reducer.count(), '', true),
    geometry: aoi,
    scale: 30,
    maxPixels: 1e9
  });

  const landCloudPixels = ee.Number(landStats.get('QA_PIXEL_sum')).getInfo();
  const landTotalPixels = ee.Number(landStats.get('QA_PIXEL_count')).getInfo();
  const landCloudCover = landTotalPixels > 0 ? (landCloudPixels / landTotalPixels) * 100 : 0;

  // 8. Calculate cloud cover over water/river areas
  const waterCloud = cloud.updateMask(water);
  const waterStats = waterCloud.reduceRegion({
    reducer: ee.Reducer.sum().combine(ee.Reducer.count(), '', true),
    geometry: aoi,
    scale: 30,
    maxPixels: 1e9
  });

  const waterCloudPixels = ee.Number(waterStats.get('QA_PIXEL_sum')).getInfo();
  const waterTotalPixels = ee.Number(waterStats.get('QA_PIXEL_count')).getInfo();
  const waterCloudCover = waterTotalPixels > 0 ? (waterCloudPixels / waterTotalPixels) * 100 : 0;

  console.log(`Land pixels: ${landTotalPixels}, Cloud pixels: ${landCloudPixels}, Cover: ${landCloudCover.toFixed(2)}%`);
  console.log(`Water pixels: ${waterTotalPixels}, Cloud pixels: ${waterCloudPixels}, Cover: ${waterCloudCover.toFixed(2)}%`);

  // 9. Validation
  if (landTotalPixels === 0 || waterTotalPixels === 0) {
    console.log('Insufficient pixels for land or water classification.');
    console.log('C2');
    return;
  }

  if (isNaN(landCloudCover) || isNaN(waterCloudCover)) {
    console.log('Invalid cloud cover calculation.');
    console.log('C3');
    return;
  }

  // 10. Compare cloud cover: is land cloud cover > water cloud cover?
  console.log(`Comparison: Land (${landCloudCover.toFixed(2)}%) vs Water (${waterCloudCover.toFixed(2)}%)`);

  if (landCloudCover > waterCloudCover) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
